cd /testbed && patch -p1 <<'PATCH'
--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,83 @@
+proc cluster_shard_for_node {id node_id} {
+    foreach shard [R $id CLUSTER SHARDS] {
+        foreach node [dict get $shard nodes] {
+            if {[dict get $node id] eq $node_id} {
+                return $shard
+            }
+        }
+    }
+    fail "Node $node_id not found in CLUSTER SHARDS on node $id"
+}
+
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set primary_ids [list [R 0 CLUSTER MYID] [R 1 CLUSTER MYID] [R 2 CLUSTER MYID]]
+    set expected_slots {{0 5461} {5462 10922} {10923 16383}}
+
+    test "CLUSTER SHARDS reports all shard slot ranges" {
+        foreach id {0 1 2 3 4 5} {
+            foreach primary_id $primary_ids slots $expected_slots {
+                assert_equal $slots [dict get [cluster_shard_for_node $id $primary_id] slots]
+            }
+        }
+    }
+
+    set paused_pid [srv 0 pid]
+    test "CLUSTER SHARDS preserves slot ranges after failover with the old primary stopped" {
+        wait_for_sync [Rn 3]
+        pause_process $paused_pid
+        wait_for_condition 1000 50 {
+            [s -3 role] eq {master}
+        } else {
+            fail "Replica did not become a primary"
+        }
+
+        foreach id {1 2 3 4 5} {
+            wait_node_marked_fail $id [lindex $primary_ids 0]
+            wait_for_condition 1000 50 {
+                [CI $id cluster_state] eq "ok"
+            } else {
+                fail "Cluster node $id did not recover after failover"
+            }
+            foreach primary_id $primary_ids slots $expected_slots {
+                set shard [cluster_shard_for_node $id $primary_id]
+                assert_equal $slots [dict get $shard slots]
+                if {$primary_id eq [lindex $primary_ids 0]} {
+                    foreach node [dict get $shard nodes] {
+                        if {[dict get $node id] eq $primary_id} {
+                            assert_equal master [dict get $node role]
+                            assert_equal fail [dict get $node health]
+                        }
+                    }
+                }
+            }
+        }
+    }
+    resume_process $paused_pid
+    wait_for_cluster_propagation
+
+    test "CLUSTER SHARDS preserves slot ranges after the old primary rejoins" {
+        foreach id {0 1 2 3 4 5} {
+            foreach primary_id $primary_ids slots $expected_slots {
+                assert_equal $slots [dict get [cluster_shard_for_node $id $primary_id] slots]
+            }
+        }
+    }
+}
+
+start_cluster 1 0 {tags {external:skip cluster}} {
+    test "CLUSTER SHARDS reports discontinuous slot ranges" {
+        R 0 CLUSTER DELSLOTS 10 12 16383
+        assert_equal {0 9 11 11 13 16382} [dict get [lindex [R 0 CLUSTER SHARDS] 0] slots]
+        assert_equal {0 9 11 11 13 16382} [dict get [lindex [R 0 CLUSTER SHARDS] 0] slots]
+    }
+
+    test "CLUSTER SHARDS reports an empty array for a shard with no slots" {
+        R 0 CLUSTER DELSLOTSRANGE 0 9 11 11 13 16382
+        set shards [R 0 CLUSTER SHARDS]
+        assert_equal 1 [llength $shards]
+        assert_equal {} [dict get [lindex $shards 0] slots]
+        assert_equal 1 [llength [dict get [lindex $shards 0] nodes]]
+    }
+}
PATCH
./runtest --single unit/cluster/cluster-shards

